test-case.test:
(: Name: Catalog001 :)
(: Description: test all input files have variable references :)
(: declare variable $input-context external; :)
<missing-variable>{
  for $x in doc("TestSources/XQFTTSCatalog.xml")//*:input-file
    [count(@variable) = 0 and ./text() != "emptydoc"]
  return string($x/../@name)
}</missing-variable>

(: Name: Catalog002 :)
(: Description: test all standard test cases have at least one output file :)
declare variable $input-context external;
<standard-no-outputfile>{
  doc("TestSources/XQFTTSCatalog.xml")//*:test-case[@scenario = "standard"][fn:count(*:output-file) = 0]/@name/string()
}</standard-no-outputfile>

(: Name: Catalog003 :)
(: Description: test all error test cases have at least one expected error :)
declare variable $input-context external;
<error-no-expected-error>{
  doc("TestSources/XQFTTSCatalog.xml")//*:test-case[@scenario = "runtime-error" or @scenario = "parse-error"][fn:count(*:expected-error) = 0 and fn:count(*:output-file[@compare = "Inspect"]) = 0]/@name/string()
}</error-no-expected-error>
